cssSegments.5085a73e0dda3874:
.home-active-syntax {
  --home-active-syntax-cycle: 8s;

  & .code-wrapper {
    height: 100%;
    mask-image: linear-gradient(90deg, #000 calc(100% - 3rem), #0000);
  }

  & .line {
    z-index: 0;
    position: relative;
  }

  & .line:after {
    z-index: -1;
    visibility: hidden;
    background: var(--color-code-active);
    opacity: 0;
    content: "";
    pointer-events: none;
    position: absolute;
    inset: -.12rem -100cqw -.08rem;
  }

  & .line:nth-child(-n+4):after {
    animation-name: home-active-syntax-line;
    animation-duration: var(--home-active-syntax-cycle);
    animation-timing-function: step-end;
    animation-iteration-count: infinite;
    animation-delay: var(--home-active-syntax-delay, 0s);
  }

  & .mcss-semantic {
    animation-name: home-active-syntax-token;
    animation-duration: var(--home-active-syntax-cycle);
    animation-timing-function: step-end;
    animation-iteration-count: infinite;
    animation-delay: var(--home-active-syntax-delay, 0s);
    position: relative;
  }

  & .line .mcss-semantic:before {
    visibility: hidden;
    background: var(--home-text);
    opacity: 0;
    content: "";
    width: 1px;
    height: 1.05em;
    animation-name: home-active-syntax-caret, home-manifest-suggestions-caret-blink;
    animation-duration: var(--home-active-syntax-cycle), 1s;
    animation-timing-function: step-end;
    animation-iteration-count: infinite;
    animation-delay: var(--home-active-syntax-delay, 0s), 0s;
    display: block;
    position: absolute;
    top: .08em;
    left: -2px;
  }

  & .line .mcss-semantic ~ .mcss-semantic:before {
    content: none;
  }

  & .line:first-child {
    --home-active-syntax-delay: 0s;
  }

  & .line:nth-child(2) {
    --home-active-syntax-delay: -6s;
  }

  & .line:nth-child(3) {
    --home-active-syntax-delay: -4s;
  }

  & .line:nth-child(4) {
    --home-active-syntax-delay: -2s;
  }
}

