cssSegments.fba5fc29de803dd9:
.home-swatch {
  --home-swatch-height: calc(var(--home-swatch-lift) * 150px * var(--home-rise) * var(--home-tilt));
  outline-offset: -1px;
  transform-style: preserve-3d;
  transform: translateZ(var(--home-swatch-height));
  border-radius: 2px;
  outline: 1px solid oklab(0% none none / .06);
  display: block;
  position: relative;

  @media (width >= 64rem){
    border-radius: 4px;
  }

  &:after {
    border-radius: inherit;
    opacity: calc(var(--home-swatch-lift) * 3 * var(--home-tilt));
    transform: translateZ(calc(var(--home-swatch-height) * -1));
    content: "";
    background: light-dark(#00000024, #00000080);
    position: absolute;
    inset: 0;
  }
}

